#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: probe Docker on a real remote msb sandbox (map ticket: "Probe Docker
# on a real remote msb sandbox"). Feeds "Where does Docker's data live in a
# remote Runner?". Source experiment: docs/research/remote-docker-in-runner.md
# on branch research/remote-docker-in-runner, "Open questions" section.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

ISSUE_REPO="arteven/gh-runners-msb"
ISSUE_NUM=13
RESULTS="${RESULTS:-/tmp/msb-remote-docker-probe.md}"
LAST_OUT=$(mktemp)
PROBE_UP=0        # dind-probe sandbox exists and booted
TMPFS_UP=0        # dind-tmpfs sandbox exists and booted
RESULT_A="not run"; RESULT_B="not run"; RESULT_C="not run"
DRIVER_A=""

# record "Heading" cmd...: run cmd, show + append its output to RESULTS as a
# fenced block, never abort the wizard on failure. Exit code lands in LAST_RC;
# output of the latest record is also in LAST_OUT.
record() {
  local title="$1"; shift
  printf '\n### %s\n\n```\n' "$title" >> "$RESULTS"
  : > "$LAST_OUT"
  set +e
  "$@" 2>&1 | tee -a "$RESULTS" "$LAST_OUT"
  LAST_RC=${PIPESTATUS[0]}
  set -e
  printf '```\n' >> "$RESULTS"
}

# sbx_exec NAME SCRIPT: run SCRIPT with sh -c inside the sandbox.
sbx_exec() { msb exec "$1" -- sh -c "$2"; }

# cleanup removes both probe sandboxes. Also runs on Ctrl-C or error so a
# half-finished run doesn't keep billing.
cleanup() {
  if (( PROBE_UP || TMPFS_UP )); then
    printf '\n  Removing probe sandboxes (they bill per running second)...\n'
    msb rm -f dind-probe dind-tmpfs >/dev/null 2>&1 || \
      printf '  If they linger, run: msb rm -f dind-probe dind-tmpfs\n'
    PROBE_UP=0; TMPFS_UP=0
  fi
  rm -f "$LAST_OUT"
}
trap cleanup EXIT

# ── Guest scripts, kept as heredocs so no shell quoting needs escaping ────
read -r -d '' GUEST_LAYOUT <<'EOF' || true
uname -r
echo "--- root mountinfo line"
awk '$5=="/"' /proc/self/mountinfo | tail -1
df -hT /
echo "--- block devices"; ls /sys/block
grep CapEff /proc/self/status
grep -E "overlay|fuse" /proc/filesystems
ip link add br-probe type bridge && ip link add v0 type veth peer name v1 && echo "bridge+veth OK" || echo "bridge+veth FAILED"
iptables -t nat -L -n >/dev/null 2>&1 && echo "iptables-nat OK" || echo "iptables-nat FAILED"
nft list ruleset >/dev/null 2>&1 && echo "nft OK" || echo "nft FAILED"
EOF

read -r -d '' GUEST_A <<'EOF' || true
fail=0
dockerd >/tmp/dockerd.log 2>&1 &
if ! timeout 60 sh -c 'until docker info >/dev/null 2>&1; do sleep 1; done'; then
  tail -50 /tmp/dockerd.log; echo "STRATEGY_A=FAIL (dockerd did not start)"; exit 1
fi
echo "DRIVER: $(docker info --format '{{.Driver}} cgroup={{.CgroupVersion}}')"
docker run --rm hello-world || fail=1
printf 'FROM alpine\nRUN echo built > /x\n' | docker build -q - || fail=1
docker run -d --name svc -p 8080:80 nginx:alpine && sleep 3 \
  && wget -qO /tmp/out localhost:8080 && head -3 /tmp/out || fail=1
if [ "$fail" = 0 ]; then echo "STRATEGY_A=PASS"; else echo "STRATEGY_A=FAIL"; fi
EOF

read -r -d '' GUEST_B <<'EOF' || true
pkill dockerd; sleep 2
rm -rf /var/lib/docker; mkdir -p /var/lib/docker
if ! { truncate -s 12G /docker.img && mkfs.ext4 -q /docker.img && mount -o loop /docker.img /var/lib/docker; }; then
  echo "STRATEGY_B=FAIL (loop mount)"; exit 1
fi
dockerd >/tmp/dockerd.log 2>&1 &
sleep 10
echo "DRIVER: $(docker info --format '{{.Driver}}')"
if docker run --rm hello-world; then echo "STRATEGY_B=PASS"; else tail -30 /tmp/dockerd.log; echo "STRATEGY_B=FAIL"; fi
EOF

read -r -d '' GUEST_C <<'EOF' || true
dockerd >/tmp/d.log 2>&1 &
sleep 10
echo "DRIVER: $(docker info --format '{{.Driver}}')"
if docker run --rm hello-world; then echo "STRATEGY_C=PASS"; else tail -30 /tmp/d.log; echo "STRATEGY_C=FAIL"; fi
EOF

# result_of FILE KEY: PASS/FAIL token for STRATEGY_<KEY>, or "no result".
result_of() { grep -o "STRATEGY_$2=[A-Z]*" "$1" | tail -1 | cut -d= -f2 || true; }

banner "Probe Docker on a real remote msb sandbox"
printf '# Remote Docker probe results\n\nRun %s\n' "$(date -u +%Y-%m-%dT%H:%MZ)" > "$RESULTS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check tools and select the remote profile"
say "This boots two short-lived sandboxes on your REAL cloud account, runs the"
say "Docker experiment from the research file, then offers to post the output"
say "to GitHub issue #$ISSUE_NUM. About 30 minutes, about \$0.10."
note "Output is saved to $RESULTS"
printf '\n'
for tool in msb curl jq; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool not found on PATH. Install it and re-run."; exit 1; }
done
say "msb, curl and jq are present."
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
  || warn "gh is not logged in: you'll have to paste the output into the issue by hand at the end."
ask MSB_CONTEXT "Name of your remote msb profile (Enter for 'remote'):"
MSB_CONTEXT="${MSB_CONTEXT:-remote}"
step "Switching profile (this changes your active msb context):"
msb context use "$MSB_CONTEXT"
confirm "Is '$MSB_CONTEXT' the cloud (remote) profile, not the local one?" \
  || { warn "Fix the profile (msb context use <name>) and re-run."; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Plan limits: GET /v1/quotas"
say "We read this account's plan quotas (disk, memory, uptime, concurrency)."
if [[ -z "${MSB_API_KEY:-}" ]]; then
  step "Open your microsandbox cloud account and copy an API key."
  ask_secret MSB_API_KEY "Paste MSB_API_KEY (hidden, not saved to disk):"
fi
export MSB_API_KEY
quotas() {
  local out
  out=$(printf 'header = "Authorization: Bearer %s"\n' "$MSB_API_KEY" \
    | curl -sS -K - https://api.microsandbox.dev/v1/quotas) || return 1
  jq . <<<"$out" 2>/dev/null || printf '%s\n' "$out"
}
record "Plan quotas (GET /v1/quotas)" quotas
(( LAST_RC == 0 )) || warn "The quotas call failed. Check the key; the rest can still run."
pause "Enter to boot the probe sandbox"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Boot the DinD probe sandbox and inspect its layout"
say "Creating dind-probe (docker:dind, 2 CPU, 4G RAM, 20G managed root, 30m max)."
record "Create dind-probe" msb create docker:dind --name dind-probe \
  --cpus 2 --memory 4G --root-disk 20G --max-duration 30m
if (( LAST_RC == 0 )); then
  PROBE_UP=1
  record "Layout, privileges, kernel features" sbx_exec dind-probe "$GUEST_LAYOUT"
else
  warn "msb create failed (likely a plan cap; compare with the quotas above)."
  warn "The failure output is saved. Continuing to the posting stage."
fi
pause "Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Strategy A: Docker as-is on the managed root"
if (( PROBE_UP )); then
  say "Starting dockerd and running hello-world, a build and a published service."
  record "Strategy A: docker as-is" sbx_exec dind-probe "$GUEST_A"
  RESULT_A=$(result_of "$LAST_OUT" A); RESULT_A="${RESULT_A:-no result}"
  DRIVER_A=$(grep -o '^DRIVER: .*' "$LAST_OUT" | head -1 || true)
  say "Strategy A: $RESULT_A  ${DRIVER_A}"
else
  note "Skipped: no probe sandbox."
fi
pause "Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Strategy B: loop-mounted ext4 file at /var/lib/docker"
if (( PROBE_UP )); then
  if [[ "$RESULT_A" == PASS && "$DRIVER_A" == *overlay* ]]; then
    note "A passed on an overlay driver, so B and C are only fallbacks."
    run_bc=0; confirm "Run B and C anyway for completeness?" && run_bc=1
  else
    run_bc=1
  fi
  if (( run_bc )); then
    record "Strategy B: loop ext4" sbx_exec dind-probe "$GUEST_B"
    RESULT_B=$(result_of "$LAST_OUT" B); RESULT_B="${RESULT_B:-no result}"
    say "Strategy B: $RESULT_B"
  else
    RESULT_B="skipped (A passed)"
  fi
else
  note "Skipped: no probe sandbox."; run_bc=0
fi
pause "Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Strategy C: tmpfs at /var/lib/docker, fresh sandbox"
if (( PROBE_UP && run_bc )); then
  record "Create dind-tmpfs" msb create docker:dind --name dind-tmpfs \
    --cpus 2 --memory 6G --tmpfs /var/lib/docker:4096 --max-duration 30m
  if (( LAST_RC == 0 )); then
    TMPFS_UP=1
    record "Strategy C: tmpfs" sbx_exec dind-tmpfs "$GUEST_C"
    RESULT_C=$(result_of "$LAST_OUT" C); RESULT_C="${RESULT_C:-no result}"
    say "Strategy C: $RESULT_C"
  else
    RESULT_C="create failed"
  fi
else
  RESULT_C="skipped"; note "Skipped."
fi
step "Removing both sandboxes now."
cleanup
pause "Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Post the output to issue #$ISSUE_NUM"
BODY=$(mktemp)
{
  printf '## Remote Docker probe results\n\n'
  printf -- '- Strategy A (docker as-is): **%s** %s\n' "$RESULT_A" "$DRIVER_A"
  printf -- '- Strategy B (loop ext4): **%s**\n' "$RESULT_B"
  printf -- '- Strategy C (tmpfs): **%s**\n' "$RESULT_C"
  cat "$RESULTS"
} > "$BODY"
say "Full output (quotas JSON, root mountinfo line, docker info Driver, strategies)"
say "is in: $BODY"
warn "Skim it first: the quotas JSON may contain account details you don't want public."
if confirm "Post it as a comment on issue #$ISSUE_NUM in $ISSUE_REPO?"; then
  if gh issue comment "$ISSUE_NUM" --repo "$ISSUE_REPO" --body-file "$BODY" >/dev/null; then
    say "Posted. Tell the agent: ticket 13 can be resolved."
  else
    SKIPPED+=("post $BODY to issue #$ISSUE_NUM by hand")
  fi
else
  SKIPPED+=("post $BODY to issue #$ISSUE_NUM by hand")
fi

finish
}

run_wizard "$@"; exit
